window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["scaling-law"]={"title":"缩放定律：用幂律规划参数、数据与算力","subtitle":"从 log-log 直线、边际收益递减到计算最优分配，再到数据质量、能力阈值与全生命周期成本。","thesis":"缩放定律是在特定模型族、数据分布和训练配方中观察到的经验规律：验证损失常随参数、数据或计算量按幂律下降。它适合做预算规划与实验外推，但不是自然常数；<b>拟合区间、数据质量、训练配方、目标指标和部署成本</b>都会改变结论。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"若 α=0.10","rule":"R=L−L∞","steps":"1.50+0.50×0.794","interpretation":"本轮只减少 20.6%"}}],"formulas":[{"id":"scaling-law-reducible-loss","section":1,"formulaIndex":1,"symbols":[{"name":"L","meaning":"给定规模下按统一口径测得的目标损失","evidence":"L(x) 是规模为 x 时测得的目标损失"},{"name":"x","meaning":"参数、训练 token 或计算量等被放大的资源尺度","evidence":"x 可以是参数数 N、训练 token 数 D 或计算量 C"},{"name":"A","meaning":"可约损失在参考资源尺度上的幅度系数","evidence":"A 决定可约部分在参考尺度上的大小"},{"name":"α","meaning":"控制可约损失随规模下降速度的正缩放指数","evidence":"α 是正的缩放指数"}]},{"id":"scaling-law-log-linearization","section":2,"formulaIndex":1,"symbols":[{"name":"log","meaning":"把乘法变加法并把幂指数变系数的对数函数","evidence":"log 是对数函数"},{"name":"L","meaning":"总损失与其不可约下限","evidence":"纵轴是 log(L−L∞)"},{"name":"A","meaning":"线性化后决定直线截距的幅度系数","evidence":"截距为 log A"},{"name":"α","meaning":"线性化后直线斜率绝对值对应的缩放指数","evidence":"直线斜率为 −α"},{"name":"x","meaning":"横轴上的模型、数据或计算资源尺度","evidence":"横轴是 log x"}]},{"id":"scaling-law-tenfold-example","section":3,"formulaIndex":1,"symbols":[{"name":"R","meaning":"总损失减不可约下限后的可约损失","evidence":"R=L−L∞ 是可约损失"},{"name":"C","meaning":"扩大前使用的原始训练计算量","evidence":"C 是原计算量"}]},{"id":"scaling-law-training-compute","section":4,"formulaIndex":1,"symbols":[{"name":"C","meaning":"训练过程中执行的总浮点运算次数","evidence":"C 是训练总 FLOPs"},{"name":"N","meaning":"稠密模型包含的参数总数量","evidence":"N 是模型参数数量"},{"name":"D","meaning":"训练过程中处理过的 token 总数量","evidence":"D 是训练中处理的 token 总数"}]},{"id":"scaling-law-lifecycle-cost","section":8,"formulaIndex":1,"symbols":[{"name":"K","meaning":"总成本或训练、推理、运维子成本","evidence":"K总 是规划期内全部成本"},{"name":"N","meaning":"规划时间范围内预计处理的请求数量","evidence":"N请求 是预计请求数量"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"缩放定律是在固定系统附近拟合资源规模与验证损失关系的经验曲线。","evidence":"对一组训练实验的统计拟合"},"problem":{"answer":"它为参数、数据或算力扩大时的边际收益与预算规划提供近似预测。","evidence":"资源增加时验证损失怎样变化"},"inputOutput":{"answer":"输入是多个规模点及同口径结果，输出是拟合参数和带不确定性的附近预测。","evidence":"输出是拟合参数与带不确定性的附近规模预测"},"mechanism":{"answer":"总损失分成难以消除的下限与按 x 负幂下降的可约部分。","evidence":"单靠继续扩大 x 难以消除的下限"},"interpretation":{"answer":"资源按相同倍数增加只会按固定比例减少剩余可约损失，边际回报递减。","evidence":"逐次增加相同倍数只能按固定比例减少剩余可约损失"},"boundary":{"answer":"规律依赖模型族、数据、配方和目标指标，不是跨系统不变的自然常数。","evidence":"不是由物理定律推导出的常数"}},{"section":2,"definition":{"answer":"对数线性化把可约损失的幂律转换成 log-log 坐标中的直线。","evidence":"对数把乘法变成加法，也把幂指数变成系数"},"problem":{"answer":"它让缩放指数可由直线斜率估计，并帮助诊断数据点是否服从同一幂律。","evidence":"幂律的指数如何从图上读出来"},"inputOutput":{"answer":"输入是规模和损失点，输出是斜率、截距、下限估计及置信区间。","evidence":"输出是斜率、截距、下限估计和置信区间"},"mechanism":{"answer":"先减不可约下限，再对资源和可约损失取同底对数，幂指数成为斜率。","evidence":"先从总损失减去下限"},"interpretation":{"answer":"斜率负 alpha 表示资源增大时可约损失下降，截距 log A 表示幅度。","evidence":"直线斜率为 −α"},"boundary":{"answer":"L∞ 估错会让图弯曲，有限区间近似直线也不能支持无限外推。","evidence":"不能把它无限外推"}},{"section":3,"definition":{"answer":"数值例用指数零点一计算十倍算力对剩余可约损失的比例改善。","evidence":"十倍资源只减少约五分之一可约损失"},"problem":{"answer":"它纠正把资源扩大十倍误解为总损失也缩到十分之一的直觉。","evidence":"能得到多少改善"},"inputOutput":{"answer":"输入是 alpha、当前损失、下限和计算倍数，输出是新可约损失与总损失预测。","evidence":"若 L∞=1.50、当前 L=2.00"},"mechanism":{"answer":"十倍规模使可约部分乘十的负零点一次方，再加回不变的损失下限。","evidence":"1.50+0.50×0.794"},"interpretation":{"answer":"零点七九四表示剩余百分之七十九点四，因此本轮改善百分之二十点六。","evidence":"本轮只减少 20.6%"},"boundary":{"answer":"只有指数、下限可信且目标规模仍在拟合区间内时，该数值外推才有意义。","evidence":"不是实际训练保证"}},{"section":4,"definition":{"answer":"计算最优分配在固定训练 FLOPs 下权衡模型参数量与训练 token 数。","evidence":"固定算力迫使参数与数据互相权衡"},"problem":{"answer":"它避免只把参数做大而令模型见到的数据过少，或模型太小形成容量瓶颈。","evidence":"为什么可训练 token 会变少"},"inputOutput":{"answer":"输入是计算预算和候选 N、D，输出是等计算实验得到的质量前沿。","evidence":"输出是等计算实验前沿"},"mechanism":{"answer":"稠密训练成本近似六乘 N 乘 D，预算固定时一项增加迫使另一项减少。","evidence":"N 翻倍，D 就约减半"},"interpretation":{"answer":"平衡点是容量不足和训练不足两类瓶颈间的经验折中，不是最大模型。","evidence":"不是“把参数堆到最大”"},"boundary":{"answer":"系数六是粗略近似，架构、序列、重计算和硬件利用都会改变墙钟成本。","evidence":"FLOPs 相同也不保证时间或质量相同"}},{"section":5,"definition":{"answer":"Kaplan 与 Chinchilla 是不同实验范围和拟合约束下得到的计算分配经验。","evidence":"模型范围、训练点、拟合方法与约束不同"},"problem":{"answer":"它解释早期结论偏大模型而后续结论强调更多训练数据为何不必矛盾。","evidence":"为什么早期结论偏向更大模型"},"inputOutput":{"answer":"输入是当前架构数据和优化器的小规模等计算实验，输出是本系统自己的前沿。","evidence":"拟合自己的前沿"},"mechanism":{"answer":"在多个规模与数据点联合拟合，再比较固定计算下不同 N-D 组合。","evidence":"一组小规模等计算实验"},"interpretation":{"answer":"很多大模型 token 不足支持增加数据，但不能把每参数 token 比例当永恒常数。","evidence":"许多大模型训练 token 不足"},"boundary":{"answer":"模型族、tokenizer、过滤或上下文变化后指数会漂移，必须重新测量。","evidence":"经验指数会漂移"}},{"section":6,"definition":{"answer":"有效数据量反映 token 的新信息、质量和覆盖，而不是只计算名义数量。","evidence":"名义 token 不等于有效数据"},"problem":{"answer":"它解释重复、错误和评测污染为何令相同 token 数具有不同训练价值。","evidence":"是否等价于一万亿个新信息 token"},"inputOutput":{"answer":"输入是数据混合、重复、质量与来源，输出是覆盖、记忆、偏差和下游收益。","evidence":"同一 D 对应不同“有效数据量”"},"mechanism":{"answer":"去重和过滤改变单位 token 信号，也可能删除稀有样本并改变语言群体分布。","evidence":"可能缩窄覆盖面、放大语言或群体偏差"},"interpretation":{"answer":"相同 D 不表示相同有效信息，必须同时报告数据配比和真实切片表现。","evidence":"数据混合比例变化"},"boundary":{"answer":"去重、过滤、重复训练和合成补技能都有收益与覆盖或回流风险。","evidence":"模型坍缩和错误回流"}},{"section":7,"definition":{"answer":"能力跳变可由连续概率越过离散判分阈值造成，不一定表示内部机制突然出现。","evidence":"准确率、pass@1 或“全部步骤正确”带有阈值"},"problem":{"answer":"它区分真实能力机制变化与准确率、pass@1 等测量方式制造的台阶。","evidence":"一定意味着模型内部突然出现了全新机制吗"},"inputOutput":{"answer":"输入是不同规模的连续损失、离散任务分数和分组结果，输出是变化曲线。","evidence":"同时画连续指标、离散指标和分组结果"},"mechanism":{"answer":"正确答案概率从低于二分之一升至高于二分之一时，损失连续但 argmax 翻转。","evidence":"会突然从错变对"},"interpretation":{"answer":"仅有离散曲线不能判断涌现来源，需在阈值附近加点并查看连续指标。","evidence":"仅凭一条离散曲线无法区分"},"boundary":{"answer":"平均损失改善不保证事实、安全或罕见能力同步改善，必须独立切片评测。","evidence":"不保证事实性、安全性或罕见能力同步改善"}},{"section":8,"definition":{"answer":"生命周期优化把一次训练、重复推理、运维与失败成本放进同一规划周期。","evidence":"训练最优不一定是产品全生命周期最优"},"problem":{"answer":"它解释多训练较小模型为何可能因长期推理更便宜而降低总成本。","evidence":"为什么多训练一个较小模型"},"inputOutput":{"answer":"输入是训练候选、请求规模和部署约束，输出是满足质量的生命周期成本前沿。","evidence":"输出是满足质量条件的生命周期成本前沿"},"mechanism":{"answer":"总成本把一次训练费用与请求数乘单次推理费用及运维失败费用相加。","evidence":"各项必须使用同一时间范围和质量门槛"},"interpretation":{"answer":"请求越多，单次推理成本权重越大，参数较小但训练更充分的模型更可能占优。","evidence":"模型每次推理的显存、延迟和能耗会重复支付"},"boundary":{"answer":"一次性研究与高流量服务的最优点不同，只优化训练 FLOPs 会转移部署成本。","evidence":"会把成本转移到部署阶段"}},{"section":9,"definition":{"answer":"外推失效是新规模点因系统或数据条件变化而偏离原缩放曲线。","evidence":"外推何时会失效"},"problem":{"answer":"它防止把小模型拟合出的直线无限延长并当作大规模质量保证。","evidence":"为什么不能无限延长"},"inputOutput":{"answer":"输入是新规模锚点及配方数据变化，输出是断点诊断、分段拟合和扩大置信区间。","evidence":"加入中间规模锚点"},"mechanism":{"answer":"架构、数据、优化或指标发生断点时，新点离开旧线，应重做消融和拟合。","evidence":"新点离开旧直线"},"interpretation":{"answer":"收益提前饱和可能是数据耗尽，异常变差也可能是训练不稳而非定律改变。","evidence":"先排查学习率、并行与数值问题"},"boundary":{"answer":"缩放定律只预测相似系统附近趋势，不能证明安全、可靠或可控。","evidence":"缩放定律是地图，不是保证书"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>由幂律推出 log-log 直线；手算十倍算力的边际收益；解释固定算力下 N 与 D 的权衡；识别外推失效和指标错位。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>缩放定律描述的是可约损失<span class=\"dd-badge math\">核心公式</span></h2><p class=\"dd-lead\">曲线为什么不断下降，却不会自动降到零？</p><p><b>缩放定律</b>是在固定模型族、数据与训练配方附近，用经验曲线描述“资源增加时验证损失怎样变化”。它不是由物理定律推导出的常数，而是对一组训练实验的统计拟合。</p><div class=\"dd-formula\" data-formula-id=\"scaling-law-reducible-loss\" data-display=\"mathml\"><math display=\"block\" aria-label=\"规模 x 下的损失 L 等于不可约下限 L 无穷，加常数 A 乘 x 的负 alpha 次方\"><mrow><mi>L</mi><mo>(</mo><mi>x</mi><mo>)</mo><mo>=</mo><msub><mi>L</mi><mo>∞</mo></msub><mo>+</mo><mi>A</mi><mo>·</mo><msup><mi>x</mi><mrow><mo>−</mo><mi>α</mi></mrow></msup></mrow></math></div><p class=\"dd-formula-note\"><code>L(x)</code> 是规模为 x 时测得的目标损失，x 可以是参数数 N、训练 token 数 D 或计算量 C。<code>L∞</code> 是在当前任务、数据和模型族中单靠继续扩大 x 难以消除的下限；<code>A</code> 决定可约部分在参考尺度上的大小，<code>α</code> 是正的缩放指数。因为 x 位于负指数上，x 增大时 <code>A·x⁻ᵅ</code> 会下降，但逐次增加相同倍数只能按固定比例减少剩余可约损失。</p><p>输入是多个规模点及其同口径验证结果，输出是拟合参数与带不确定性的附近规模预测。先问纵轴是训练损失、验证交叉熵还是能力分数；不同指标不能直接共用一条曲线。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>为什么 log-log 图上会出现直线<span class=\"dd-badge math\">推导</span></h2><p class=\"dd-lead\">幂律的指数如何从图上读出来？</p><p>对数把乘法变成加法，也把幂指数变成系数。先从总损失减去下限，只保留可约损失，再对两边取相同底数的对数：</p><div class=\"dd-formula\" data-formula-id=\"scaling-law-log-linearization\" data-display=\"mathml\"><math display=\"block\" aria-label=\"损失减下限的对数，等于 A 的对数减 alpha 乘规模 x 的对数\"><mrow><mi>log</mi><mo>(</mo><mi>L</mi><mo>−</mo><msub><mi>L</mi><mo>∞</mo></msub><mo>)</mo><mo>=</mo><mi>log</mi><mi>A</mi><mo>−</mo><mi>α</mi><mo>·</mo><mi>log</mi><mi>x</mi></mrow></math></div><p class=\"dd-formula-note\"><code>log</code> 是对数函数；只要横纵轴使用同一对数底，斜率结论不变。横轴是 <code>log x</code>，纵轴是 <code>log(L−L∞)</code>，直线斜率为 <code>−α</code>，截距为 <code>log A</code>。若 L∞ 估错，纵轴就不是正确的可约损失，图会弯曲并误估指数。</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 720 285\" role=\"img\" aria-label=\"普通坐标中的递减曲线与对数坐标中的直线\"><defs><marker id=\"sl-arrow\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#7b8494\"/></marker></defs><rect x=\"22\" y=\"25\" width=\"315\" height=\"225\" rx=\"10\" fill=\"#21252d\" stroke=\"#596273\"/><line x1=\"65\" y1=\"215\" x2=\"310\" y2=\"215\" stroke=\"#8791a2\" marker-end=\"url(#sl-arrow)\"/><line x1=\"65\" y1=\"215\" x2=\"65\" y2=\"52\" stroke=\"#8791a2\" marker-end=\"url(#sl-arrow)\"/><path d=\"M78,70 C120,115 165,150 225,174 C255,186 282,193 305,197\" fill=\"none\" stroke=\"#65a6d9\" stroke-width=\"3\"/><line x1=\"72\" y1=\"200\" x2=\"307\" y2=\"200\" stroke=\"#d48b78\" stroke-dasharray=\"6 5\"/><text x=\"186\" y=\"239\" text-anchor=\"middle\" class=\"svg-t\">规模 x</text><text x=\"104\" y=\"193\" class=\"svg-t\" font-size=\"11\">L∞</text><text x=\"178\" y=\"45\" text-anchor=\"middle\" class=\"svg-t\">普通坐标：向下弯曲</text><rect x=\"382\" y=\"25\" width=\"315\" height=\"225\" rx=\"10\" fill=\"#21252d\" stroke=\"#596273\"/><line x1=\"425\" y1=\"215\" x2=\"670\" y2=\"215\" stroke=\"#8791a2\" marker-end=\"url(#sl-arrow)\"/><line x1=\"425\" y1=\"215\" x2=\"425\" y2=\"52\" stroke=\"#8791a2\" marker-end=\"url(#sl-arrow)\"/><line x1=\"445\" y1=\"78\" x2=\"650\" y2=\"190\" stroke=\"#65a6d9\" stroke-width=\"3\"/><path d=\"M500,95 L500,129 L556,129\" fill=\"none\" stroke=\"#d3a05a\"/><text x=\"522\" y=\"120\" class=\"svg-t\" font-size=\"11\">斜率 −α</text><text x=\"547\" y=\"239\" text-anchor=\"middle\" class=\"svg-t\">log x</text><text x=\"540\" y=\"45\" text-anchor=\"middle\" class=\"svg-t\">log-log：近似直线</text></svg><figcaption>图 1　同一幂律在两种坐标系中的形状；只有减去 L∞ 后，log-log 线性关系才严格对应公式。</figcaption></figure><p>实际输入是多个 x 与损失点，输出是斜率、截距、下限估计和置信区间。点只在有限区间近似成直线时，不能把它无限外推。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>数值例子：十倍资源只减少约五分之一可约损失<span class=\"dd-badge math\">算例</span></h2><p class=\"dd-lead\">若 α=0.10，把计算量扩大十倍能得到多少改善？</p><div class=\"dd-formula\" data-formula-id=\"scaling-law-tenfold-example\" data-display=\"mathml\"><math display=\"block\" aria-label=\"十倍计算后可约损失与原可约损失之比，等于十的负零点一次方，约为零点七九四\"><mrow><mfrac><msub><mi>R</mi><mn>2</mn></msub><msub><mi>R</mi><mn>1</mn></msub></mfrac><mo>=</mo><msup><mrow><mo>(</mo><mfrac><mrow><mn>10</mn><mi>C</mi></mrow><mi>C</mi></mfrac><mo>)</mo></mrow><mrow><mo>−</mo><mn>0.10</mn></mrow></msup><mo>=</mo><msup><mn>10</mn><mrow><mo>−</mo><mn>0.10</mn></mrow></msup><mo>≈</mo><mn>0.794</mn></mrow></math></div><p class=\"dd-formula-note\"><code>R=L−L∞</code> 是可约损失，<code>R₁</code> 和 <code>R₂</code> 分别是扩算力前后剩余的可约部分，<code>C</code> 是原计算量，指数 <code>−0.10</code> 来自假设的 α=0.10。比值 0.794 表示剩余 79.4%，所以本轮只减少 20.6%，不是损失变为原来的十分之一。</p><p>若 L∞=1.50、当前 L=2.00，则 R=0.50，十倍算力后的预测是 1.50+0.50×0.794≈<b>1.897</b>，并不是 1.59。再扩大十倍，仍只是把当时剩余的可约部分乘以 0.794。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>计算倍数</th><th>可约损失比例</th><th>若 L∞=1.50、起点 L=2.00</th></tr></thead><tbody><tr><td>1×</td><td>1.000</td><td>2.000</td></tr><tr><td>10×</td><td>0.794</td><td>1.897</td></tr><tr><td>100×</td><td>0.631</td><td>1.816</td></tr></tbody></table></div><p>这个结果只是在 α 与 L∞ 估计可信、且十倍规模仍处于拟合区间时的外推，不是实际训练保证。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>固定算力迫使参数与数据互相权衡<span class=\"dd-badge math\">计算最优</span></h2><p class=\"dd-lead\">模型做大以后，为什么可训练 token 会变少？</p><p>对稠密 Transformer，一次 token 的前向加反向计算大致与参数量成正比，因此预训练总浮点运算数常粗略写成：</p><div class=\"dd-formula\" data-formula-id=\"scaling-law-training-compute\"><math display=\"block\" aria-label=\"训练计算量 C 约等于六乘模型参数量 N 乘训练 token 数 D\"><mrow><mi>C</mi><mo>≈</mo><mn>6</mn><mi>N</mi><mi>D</mi></mrow></math></div><p class=\"dd-formula-note\"><code>C</code> 是训练总 FLOPs，FLOPs 指执行的浮点运算次数；<code>N</code> 是模型参数数量，<code>D</code> 是训练中处理的 token 总数。系数 6 是常见稠密 Transformer 前向与反向成本的粗略近似，不是所有架构的固定常数。</p><p>预算 C 固定时，N 翻倍，D 就约减半。参数太少会容量不足；参数太多却只见少量 token，会训练不足。计算最优点是两类瓶颈的经验平衡，不是“把参数堆到最大”。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>同一预算下的方案</th><th>参数 N</th><th>token D</th><th>典型风险</th></tr></thead><tbody><tr><td>A：偏小模型</td><td>1×</td><td>8×</td><td>容量瓶颈</td></tr><tr><td>B：平衡点</td><td>2×</td><td>4×</td><td>需实验确认</td></tr><tr><td>C：偏大模型</td><td>4×</td><td>2×</td><td>数据不足、推理昂贵</td></tr></tbody></table></div><p>输入是计算预算与候选 N、D，输出是等计算实验前沿。注意力长度、稀疏结构、重计算和硬件利用率都会改变实际墙钟成本，所以 FLOPs 相同也不保证时间或质量相同。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>Kaplan 与 Chinchilla 不是互相矛盾的口号<span class=\"dd-badge intuition\">研究史</span></h2><p class=\"dd-lead\">为什么早期结论偏向更大模型，后来研究又强调更多数据？</p><p>两项研究使用的模型范围、训练点、拟合方法与约束不同。Kaplan 等人的实验支持平滑幂律，并给出较偏向增大参数的预算分配；Chinchilla 用更多规模点联合拟合后指出，许多大模型训练 token 不足，固定计算下应同步增加参数与数据。</p><p>真正可迁移的方法是：用当前架构、数据与优化器做一组小规模等计算实验，拟合自己的前沿，而不是把“每参数多少 token”当成永恒常数。</p><div class=\"dd-note warn\"><b>经验指数会漂移。</b>模型族、tokenizer、数据过滤和上下文长度改变后，应重新测量；跨论文直接抄指数可能比不拟合更危险。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>名义 token 不等于有效数据<span class=\"dd-badge eng\">数据质量</span></h2><p class=\"dd-lead\">一万亿个重复、污染或低质量 token，是否等价于一万亿个新信息 token？</p><p>重复内容的边际信息低，错误内容可能教会错误规律，评测污染会制造虚假能力。过滤与去重提高单 token 价值，却也可能缩窄覆盖面、放大语言或群体偏差。数据混合比例变化会让同一 D 对应不同“有效数据量”。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>变化</th><th>可能收益</th><th>必须监控</th></tr></thead><tbody><tr><td>去重</td><td>减少记忆与浪费</td><td>稀有样本是否误删</td></tr><tr><td>质量过滤</td><td>提高平均信号</td><td>领域/语言覆盖偏移</td></tr><tr><td>重复多轮</td><td>榨取有限数据</td><td>过拟合与记忆</td></tr><tr><td>合成数据</td><td>补足目标技能</td><td>模型坍缩和错误回流</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>损失平滑下降，能力分数仍可能跳变<span class=\"dd-badge intuition\">指标</span></h2><p class=\"dd-lead\">“涌现”一定意味着模型内部突然出现了全新机制吗？</p><p>交叉熵是连续平均量，而准确率、pass@1 或“全部步骤正确”带有阈值。模型对正确答案的概率从 0.45 升到 0.55，损失连续改善，但 argmax 准确率会突然从错变对；样本混合也会制造台阶。反过来，平均损失变好不保证事实性、安全性或罕见能力同步改善。</p><p>因此应同时画连续指标、离散指标和分组结果，并在阈值附近增加规模点。所谓涌现可以是真实机制变化，也可能是测量方式的产物；仅凭一条离散曲线无法区分。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>训练最优不一定是产品全生命周期最优<span class=\"dd-badge eng\">部署</span></h2><p class=\"dd-lead\">为什么多训练一个较小模型，反而可能让总成本更低？</p><p>若服务海量请求，模型每次推理的显存、延迟和能耗会重复支付。一个参数较少、训练 token 更多的模型，预训练可能更贵，却可能在生命周期中更便宜。反之，一次性研究模型的推理量很小，训练前沿可能更重要。</p><div class=\"dd-formula\" data-formula-id=\"scaling-law-lifecycle-cost\"><math display=\"block\" aria-label=\"全生命周期总成本等于一次训练成本，加请求总数乘单次推理成本，再加运维与失败成本\"><mrow><msub><mi>K</mi><mtext>总</mtext></msub><mo>=</mo><msub><mi>K</mi><mtext>训练</mtext></msub><mo>+</mo><msub><mi>N</mi><mtext>请求</mtext></msub><mo>·</mo><msub><mi>K</mi><mtext>单次推理</mtext></msub><mo>+</mo><msub><mi>K</mi><mtext>运维与失败</mtext></msub></mrow></math></div><p class=\"dd-formula-note\"><code>K总</code> 是规划期内全部成本，<code>K训练</code> 是一次性训练与实验成本，<code>N请求</code> 是预计请求数量，<code>K单次推理</code> 包含每次服务的硬件、能耗和延迟代价，<code>K运维与失败</code> 包含部署、监控、回退和错误处理。各项必须使用同一时间范围和质量门槛。</p><p>输入是训练候选、请求规模、上下文、并发、量化、硬件和质量约束，输出是满足质量条件的生命周期成本前沿。只优化训练 FLOPs，会把成本转移到部署阶段。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>外推何时会失效<span class=\"dd-badge eng\">边界</span></h2><p class=\"dd-lead\">从小模型拟合的直线，为什么不能无限延长？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>断点来源</th><th>表现</th><th>应对</th></tr></thead><tbody><tr><td>架构/配方改变</td><td>新点离开旧直线</td><td>分段拟合并重做消融</td></tr><tr><td>数据耗尽或分布变更</td><td>收益提前饱和</td><td>报告数据混合与有效 token</td></tr><tr><td>优化不稳定</td><td>大规模点异常变差</td><td>先排查学习率、并行与数值问题</td></tr><tr><td>指标触顶/阈值</td><td>损失与任务分数脱钩</td><td>换连续指标并做切片</td></tr><tr><td>超出拟合区间</td><td>置信区间迅速扩大</td><td>加入中间规模锚点</td></tr></tbody></table></div><div class=\"dd-note warn\"><b>缩放定律是地图，不是保证书。</b>它预测“相似系统在附近规模”的趋势，不能证明安全、可靠、可控，也不能替代目标任务评测。</div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">10</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">会套公式只是起点，可靠决策还需要实验设计与指标意识。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>规模翻倍，能力也翻倍</td><td>幂律意味着边际收益递减</td></tr><tr><td>一条直线适用于所有模型</td><td>指数依赖模型族、数据和配方</td></tr><tr><td>token 数相同，训练价值相同</td><td>质量、重复和分布决定有效信息</td></tr><tr><td>验证损失能代表全部能力</td><td>具体能力、安全和事实性要独立评测</td></tr><tr><td>训练最优就是部署最优</td><td>高请求量时推理成本会改写最优点</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>交叉熵、对数、模型训练、FLOPs</td></tr><tr><td><b>本页核心</b></td><td>幂律、计算最优、有效数据、外推边界</td></tr><tr><td>系统</td><td>分布式训练、推理优化、量化</td></tr><tr><td>研究</td><td>数据配比、涌现测量、生命周期优化</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">11</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>选择同一模型族与稳定训练配方</li><li>在多个 N、D、C 点训练</li><li>拟合 L∞、A 与 α</li><li>固定预算寻找 N–D 前沿</li><li>用中间规模检验外推</li><li>以任务切片和生命周期成本验收</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">12</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>α=0.1 时，十倍资源使可约损失变为多少？</li><li>为什么要先减去 L∞ 再取对数？</li><li>固定 C≈6ND 时，N 翻倍意味着什么？</li><li>为什么名义 token 数不能直接跨数据集比较？</li><li>何时训练计算最优不等于产品最优？</li><li>假设“缩放定律：用幂律规划参数、数据与算力”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>乘以 10⁻⁰·¹≈0.794，即减少约20.6%。</li><li>幂律作用于可约损失 L−L∞；直接对 L 取对数通常不会得到严格直线。</li><li>在近似成立时 D 约减半，因此可能从容量瓶颈转为数据不足。</li><li>重复、质量、污染和分布让每个 token 的有效信息不同。</li><li>推理请求很多，或延迟、显存、能耗约束主导全生命周期成本时。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/2001.08361\" target=\"_blank\" rel=\"noopener\">Scaling Laws for Neural Language Models</a>：参数、数据与计算的经验幂律</li><li><a href=\"https://arxiv.org/abs/2203.15556\" target=\"_blank\" rel=\"noopener\">Training Compute-Optimal Large Language Models</a>：Chinchilla 计算最优训练</li><li><a href=\"https://arxiv.org/abs/2206.07682\" target=\"_blank\" rel=\"noopener\">Emergent Abilities of Large Language Models</a>：能力随规模变化的观测</li><li><a href=\"https://arxiv.org/abs/2304.15004\" target=\"_blank\" rel=\"noopener\">Are Emergent Abilities of Large Language Models a Mirage?</a>：离散指标与阈值效应</li><li><a href=\"https://arxiv.org/abs/2401.00448\" target=\"_blank\" rel=\"noopener\">Beyond Chinchilla-Optimal</a>：把推理需求纳入生命周期优化</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
